# ==================== UTILITY FUNCTIONS ====================
def rastrigin_2d(pos):
    x, y = pos[0], pos[1]
    return 20 + (x**2 - 10 * np.cos(2 * np.pi * x)) + (y**2 - 10 * np.cos(2 * np.pi * y))

def sphere_10d(pos):
    return np.sum(pos**2)

# ==================== TASK 1: CLAMPING vs REFLECTING BOUNDARY ====================
