def pso_with_boundary(boundary_type, num_particles, iterations, dim, bounds, fitness_func, w, c1, c2, v_max):
    lower, upper = bounds
    positions = np.random.uniform(lower, upper, (num_particles, dim))
    velocities = np.random.uniform(-1, 1, (num_particles, dim))
    pbest_positions = positions.copy()
    pbest_values = np.array([fitness_func(p) for p in positions])
    gbest_idx = np.argmin(pbest_values)
    gbest_position = pbest_positions[gbest_idx].copy()
    convergence = []
    
    for i in range(iterations):
        r1 = np.random.rand(num_particles, dim)
        r2 = np.random.rand(num_particles, dim)
        velocities = w * velocities + c1 * r1 * (pbest_positions - positions) + c2 * r2 * (gbest_position - positions)
        velocities = np.clip(velocities, -v_max, v_max)
        positions = positions + velocities
        
        if boundary_type == "clamping":
            positions = np.clip(positions, lower, upper)
        elif boundary_type == "reflecting":
            for d in range(dim):
                below = positions[:, d] < lower
                above = positions[:, d] > upper
                positions[below, d] = lower - (positions[below, d] - lower)
                positions[above, d] = upper - (positions[above, d] - upper)
                velocities[below, d] = -velocities[below, d]
                velocities[above, d] = -velocities[above, d]
        
        current_values = np.array([fitness_func(p) for p in positions])
        for j in range(num_particles):
            if current_values[j] < pbest_values[j]:
                pbest_values[j] = current_values[j]
                pbest_positions[j] = positions[j].copy()
        gbest_position = pbest_positions[np.argmin(pbest_values)].copy()
        convergence.append(fitness_func(gbest_position))
    
    return gbest_position, convergence, positions

