# TASK 6: Random Search Comparison
def random_search(fitness_func, dim, bounds, num_samples, runs=10):
    lower, upper = bounds
    results = []
    for run in range(runs):
        samples = np.random.uniform(lower, upper, (num_samples, dim))
        fits = np.array([fitness_func(s) for s in samples])
        results.append(np.min(fits))
    return np.mean(results), np.std(results)

