print(f"  Q={Q}, n_ants={n_ants}, n_iterations={n_iterations}")

# ─── Full ACO Function (reusable for all tasks) ───────────────────────────────
def run_aco(distances, n_ants=10, n_iterations=50,
            alpha=1, beta=2, evaporation=0.5, Q=100, seed=42):
    random.seed(seed)
    np.random.seed(seed)

    n_cities = len(distances)
    pheromone = np.ones((n_cities, n_cities))

    def calculate_distance(path):
        return (sum(distances[path[i]][path[i+1]] for i in range(len(path)-1))
                + distances[path[-1]][path[0]])

    global_best_distance = float("inf")
    global_best_path     = None
    history              = []

    for iteration in range(n_iterations):
        all_paths     = []
        all_distances = []

        for ant in range(n_ants):
            visited = [random.randint(0, n_cities - 1)]

            while len(visited) < n_cities:
                current = visited[-1]
                probabilities = []

                for city in range(n_cities):
                    if city not in visited:
                        tau = pheromone[current][city] ** alpha
                        eta = (1 / distances[current][city]) ** beta
                        probabilities.append(tau * eta)
                    else:
                        probabilities.append(0)

                probabilities = np.array(probabilities)
                probabilities /= probabilities.sum()

                next_city = np.random.choice(range(n_cities), p=probabilities)
                visited.append(next_city)

            dist = calculate_distance(visited)
            all_paths.append(visited)
            all_distances.append(dist)

            if dist < global_best_distance:
                global_best_distance = dist
                global_best_path     = visited[:]

        history.append(global_best_distance)
        pheromone *= (1 - evaporation)

        for path, dist in zip(all_paths, all_distances):
            for i in range(len(path) - 1):
                pheromone[path[i]][path[i+1]] += Q / dist
                pheromone[path[i+1]][path[i]] += Q / dist
            pheromone[path[-1]][path[0]] += Q / dist
            pheromone[path[0]][path[-1]] += Q / dist

    return global_best_path, global_best_distance, history

