def greedy_tsp(distances, start=0):
    n = len(distances)
    visited = [start]
    unvisited = list(range(n))
    unvisited.remove(start)
    while unvisited:
        current = visited[-1]
        nearest = min(unvisited, key=lambda c: distances[current][c])
        visited.append(nearest)
        unvisited.remove(nearest)
    total = (sum(distances[visited[i]][visited[i+1]] for i in range(n-1))
             + distances[visited[-1]][visited[0]])
    return visited, total

